import{_ as a,o as t,c as s,ae as o}from"./chunks/framework.BajMXG5H.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md"}'),r={name:"reference/faq.md"};function i(n,e,h,d,l,c){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="is-orchestra-free" tabindex="-1">Is Orchestra free? <a class="header-anchor" href="#is-orchestra-free" aria-label="Permalink to &quot;Is Orchestra free?&quot;">​</a></h2><p>Yes, Orchestra is completely free to use.</p><h2 id="does-it-send-my-data-anywhere" tabindex="-1">Does it send my data anywhere? <a class="header-anchor" href="#does-it-send-my-data-anywhere" aria-label="Permalink to &quot;Does it send my data anywhere?&quot;">​</a></h2><p>No. All data stays on your local machine. The hook server runs on <code>localhost:3008</code> and only accepts connections from your local Claude Code sessions. No data is sent to any external server.</p><h2 id="which-ai-coding-agents-are-supported" tabindex="-1">Which AI coding agents are supported? <a class="header-anchor" href="#which-ai-coding-agents-are-supported" aria-label="Permalink to &quot;Which AI coding agents are supported?&quot;">​</a></h2><p>Currently, Orchestra supports <strong>Claude Code</strong> via its Hooks system. Support for additional agents may be added in the future.</p><h2 id="what-are-the-system-requirements" tabindex="-1">What are the system requirements? <a class="header-anchor" href="#what-are-the-system-requirements" aria-label="Permalink to &quot;What are the system requirements?&quot;">​</a></h2><ul><li>macOS 11.0+ (Big Sur or later)</li><li>Apple Silicon (M1/M2/M3/M4)</li><li>tmux (for session jumping)</li><li>Claude Code installed</li></ul><h2 id="how-do-i-install-orchestra" tabindex="-1">How do I install Orchestra? <a class="header-anchor" href="#how-do-i-install-orchestra" aria-label="Permalink to &quot;How do I install Orchestra?&quot;">​</a></h2><p>The recommended way is via Homebrew:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zeroshotlog/tap/orchestra</span></span></code></pre></div><p>Alternatively, download the DMG from the <a href="https://github.com/zeroshotlog/orchestra/releases" target="_blank" rel="noreferrer">Releases page</a>.</p><h2 id="how-do-i-uninstall-orchestra" tabindex="-1">How do I uninstall Orchestra? <a class="header-anchor" href="#how-do-i-uninstall-orchestra" aria-label="Permalink to &quot;How do I uninstall Orchestra?&quot;">​</a></h2><ol><li>Quit Orchestra if it&#39;s running</li><li>Delete <code>Orchestra.app</code> from <code>/Applications</code></li><li>Remove the hook configuration from <code>~/.claude/settings.json</code></li></ol><h2 id="can-i-use-orchestra-without-tmux" tabindex="-1">Can I use Orchestra without tmux? <a class="header-anchor" href="#can-i-use-orchestra-without-tmux" aria-label="Permalink to &quot;Can I use Orchestra without tmux?&quot;">​</a></h2><p>Orchestra will still monitor your sessions without tmux, but the &quot;Jump to session&quot; feature requires tmux to work. Sessions running outside tmux will appear in the dashboard but won&#39;t have a Jump button.</p><h2 id="does-orchestra-work-with-claude-code-agent-teams" tabindex="-1">Does Orchestra work with Claude Code Agent Teams? <a class="header-anchor" href="#does-orchestra-work-with-claude-code-agent-teams" aria-label="Permalink to &quot;Does Orchestra work with Claude Code Agent Teams?&quot;">​</a></h2><p>Yes. When you use Claude Code&#39;s Agent Teams feature, Orchestra automatically detects team members running in the same tmux window. Team sessions are displayed with rainbow-colored borders, with the Lead and Member roles clearly labeled. Make sure the <code>TeammateIdle</code> and <code>TaskCompleted</code> hooks are configured for team detection to work.</p><h2 id="how-many-hook-events-do-i-need-to-configure" tabindex="-1">How many hook events do I need to configure? <a class="header-anchor" href="#how-many-hook-events-do-i-need-to-configure" aria-label="Permalink to &quot;How many hook events do I need to configure?&quot;">​</a></h2><p>For full functionality, configure all 13 hook events: PreToolUse, PostToolUse, Stop, Notification, SubagentStart, SubagentStop, SessionStart, SessionEnd, UserPromptSubmit, PermissionRequest, PreCompact, TeammateIdle, and TaskCompleted. See the <a href="/orchestra/docs/guide/getting-started.html">Getting Started</a> guide for the complete configuration.</p><h2 id="does-orchestra-track-subagents" tabindex="-1">Does Orchestra track subagents? <a class="header-anchor" href="#does-orchestra-track-subagents" aria-label="Permalink to &quot;Does Orchestra track subagents?&quot;">​</a></h2><p>Yes. When Claude Code spawns subagents (via the Task tool), Orchestra tracks the number of active subagents per session. The session card shows the current subagent count and displays a &quot;Delegating&quot; activity status.</p><h2 id="can-i-switch-between-grid-and-list-views" tabindex="-1">Can I switch between grid and list views? <a class="header-anchor" href="#can-i-switch-between-grid-and-list-views" aria-label="Permalink to &quot;Can I switch between grid and list views?&quot;">​</a></h2><p>Yes. Use <code>⌘1</code> for grid view or <code>⌘2</code> for list view, or select from the <strong>View</strong> menu. Grid view shows detailed session cards, while list view provides a compact row-based layout.</p><h2 id="what-is-the-pomodoro-timer" tabindex="-1">What is the Pomodoro Timer? <a class="header-anchor" href="#what-is-the-pomodoro-timer" aria-label="Permalink to &quot;What is the Pomodoro Timer?&quot;">​</a></h2><p>Orchestra includes a built-in Pomodoro timer to help you manage focused work sessions. You can customize work/break durations, cycle counts, and timer size from the <strong>Orchestra</strong> menu → <strong>Pomodoro Timer</strong>. The timer supports drag-and-drop repositioning and automatic work/break cycling.</p><h2 id="what-are-agent-badges" tabindex="-1">What are Agent Badges? <a class="header-anchor" href="#what-are-agent-badges" aria-label="Permalink to &quot;What are Agent Badges?&quot;">​</a></h2><p>Agent badges show which AI coding agent is running each session (e.g., Claude, Codex, Gemini). They are automatically detected from hook events. You can toggle badge visibility from <strong>Orchestra</strong> menu → <strong>Show Agent Badges</strong>.</p><h2 id="can-i-search-and-filter-sessions" tabindex="-1">Can I search and filter sessions? <a class="header-anchor" href="#can-i-search-and-filter-sessions" aria-label="Permalink to &quot;Can I search and filter sessions?&quot;">​</a></h2><p>Yes. Press <code>⌘F</code> to focus the search bar and filter sessions by title. When multiple tmux sessions are detected, tabs appear at the top for quick filtering by tmux session.</p>',31)])])}const p=a(r,[["render",i]]);export{m as __pageData,p as default};
